  permissionScopeMetadata: { 'zh-CN': '仓库元数据（Metadata）：列出已安装仓库', 'zh-TW': '倉庫中繼資料（Metadata）：列出已安裝倉庫', en: 'ModRepository metadata: list installed repositories', ko: '저장소 메타데이터: 설치된 저장소 나열', ja: 'リポジトリメタデータ: 導入済みリポジトリの一覧表示', de: "ModRepository-Metadaten: Liste der installierten Repositorien", fr: "Métadonnées ModRepository: liste des dépôts installés", it: "ModRepository metadati: elenco repository installati", 'es-ES': "Metadatos ModRepository: lista de repositorios instalados", ru: "Метаданные ModRepository: список установленных репозиториев", pl: "ModRepozytorium metadanych: lista zainstalowanych repozytoriów", 'pt-BR': "Metadados do ModRepository: lista os repositórios instalados" },
